/* UNIFIED EDITORIAL NAV + MOBILE LEGIBILITY · 2026-08-14 */
.contents-section{
  position:relative!important;
  overflow:hidden!important;
  background:
    radial-gradient(circle at 82% 14%,rgba(72,135,116,.22),transparent 34%),
    linear-gradient(145deg,#062b27 0%,#0a3932 52%,#062823 100%)!important;
}
.contents-section .section-heading{max-width:860px!important;margin-bottom:54px!important}
.contents-section .section-heading h2{max-width:780px!important;text-wrap:balance!important}
.contents-grid{
  display:grid!important;
  grid-template-columns:repeat(4,minmax(0,1fr))!important;
  gap:12px!important;
  border:0!important;
  background:transparent!important;
}
.contents-grid>a{
  position:relative!important;
  box-sizing:border-box!important;
  min-width:0!important;
  min-height:164px!important;
  display:grid!important;
  grid-template-columns:1fr 38px!important;
  grid-template-rows:auto 1fr auto!important;
  gap:8px 12px!important;
  padding:24px 24px 22px!important;
  overflow:hidden!important;
  border:1px solid rgba(224,238,231,.20)!important;
  border-radius:22px!important;
  background:
    linear-gradient(145deg,rgba(255,255,255,.105),rgba(255,255,255,.035))!important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.16),
    0 18px 45px rgba(0,18,15,.16)!important;
  backdrop-filter:blur(14px) saturate(112%)!important;
  -webkit-backdrop-filter:blur(14px) saturate(112%)!important;
  transition-property:transform,background-color,border-color,box-shadow!important;
  transition-duration:.28s!important;
  color:#f6f0e3!important;
}
.contents-grid>a:after{
  content:""!important;
  position:absolute!important;
  inset:0!important;
  pointer-events:none!important;
  background:linear-gradient(115deg,rgba(255,255,255,.08),transparent 38%)!important;
}
.contents-grid>a:before{
  content:"↗"!important;
  position:static!important;
  grid-column:2!important;
  grid-row:1!important;
  width:36px!important;
  height:36px!important;
  display:grid!important;
  place-items:center!important;
  justify-self:end!important;
  border:1px solid rgba(240,235,216,.34)!important;
  border-radius:50%!important;
  background:rgba(255,255,255,.055)!important;
  color:#f5ead0!important;
  font:500 14px/1 Arial,sans-serif!important;
  opacity:1!important;
}
.contents-grid>a:hover{
  transform:translateY(-4px)!important;
  border-color:rgba(229,195,126,.42)!important;
  background:linear-gradient(145deg,rgba(255,255,255,.14),rgba(255,255,255,.05))!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.2),0 22px 50px rgba(0,18,15,.24)!important;
}
.contents-grid>a>span{
  grid-column:1!important;
  grid-row:1!important;
  align-self:center!important;
  color:#e6bb70!important;
  font:italic 500 25px/1 Georgia,serif!important;
  font-variant-numeric:tabular-nums!important;
}
.contents-grid>a>b{
  grid-column:1/-1!important;
  grid-row:2!important;
  align-self:end!important;
  margin:18px 0 0!important;
  color:#fbf6e9!important;
  font:500 24px/1.22 Georgia,"Songti SC","Noto Serif SC",serif!important;
  letter-spacing:-.01em!important;
  text-wrap:balance!important;
}
.contents-grid>a>em{
  grid-column:1/-1!important;
  grid-row:3!important;
  display:block!important;
  max-width:22em!important;
  margin:0!important;
  color:rgba(224,236,229,.76)!important;
  font:400 12px/1.55 Arial,"PingFang SC",sans-serif!important;
  font-style:normal!important;
  overflow-wrap:break-word!important;
}

/* Route summary: readable first, glass second */
.day-route-map>.route-mobile-summary,.day .route-mobile-summary{
  box-sizing:border-box!important;
  background:linear-gradient(135deg,rgba(230,238,234,.96),rgba(198,216,207,.94))!important;
  border:1px solid rgba(255,255,255,.72)!important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.82),0 14px 32px rgba(3,34,29,.15)!important;
}
.route-title,.route-title small,.route-title b{opacity:1!important}
.route-title small{color:#9a5c48!important;font-weight:750!important}
.route-title b{color:#143c35!important;text-shadow:none!important}
.route-glass-button{
  color:#143c35!important;
  background:linear-gradient(145deg,#fbfcf8,#dfebe5)!important;
  border:1px solid rgba(255,255,255,.9)!important;
  box-shadow:inset 0 1px 0 #fff,0 9px 20px rgba(5,47,40,.14)!important;
}

