function openTicketVault(button){var key=button.dataset.ticketKey,name=button.dataset.ticketName,modal=document.createElement('div');modal.className='trip-ticket-overlay';modal.innerHTML='<section class="trip-ticket-panel" role="dialog" aria-modal="true" aria-label="票价收藏夹"><header><div><small>TICKET VAULT · 本机保存</small><h3>'+esc(name)+'</h3></div><button type="button" data-ticket-close aria-label="关闭">×</button></header><form><label>按钮名称（可选）<input name="title" maxlength="60" placeholder="例如：门票 / 预约单 / 小红书攻略"></label><label>网页或小红书分享链接<input name="url" type="text" inputmode="url" placeholder="可粘贴网址或整段小红书分享文字"></label><button type="submit">保存链接</button><label class="trip-ticket-file">＋ 上传 PDF 或图片<input name="file" type="file" accept="application/pdf,image/*"></label></form><div class="trip-ticket-list"></div><p class="trip-ticket-note">支持普通网页、小红书分享文字、图片和 PDF；保存后均可编辑或删除。内容只保存在当前设备。</p></section>';document.body.appendChild(modal);var list=$('.trip-ticket-list',modal),form=$('form',modal),file=form.elements.file;function close(){modal.remove()}$('[data-ticket-close]',modal).onclick=close;modal.onclick=function(e){if(e.target===modal)close()};form.onsubmit=function(e){e.preventDefault();var url=extractSavedUrl(form.elements.url.value);if(!url){toast('没有识别到有效链接');return}var isXhs=/xhslink\.(?:cn|com)|xiaohongshu\.com/i.test(url);ticketPut({id:crypto.randomUUID(),placeKey:key,title:form.elements.title.value.trim()||(isXhs?'小红书攻略':url),url:url,createdAt:Date.now()}).then(function(){form.reset();renderTicketShortcuts(document);toast('链接已收藏');close()})};file.onchange=function(){var f=file.files[0];if(!f)return;if(f.size>20*1024*1024){toast('文件请控制在20MB以内');file.value='';return}var suggested=form.elements.title.value.trim()||f.name.replace(/\.[^.]+$/,'');var title=prompt('给这个附件按钮命名',suggested);if(title===null){file.value='';return}title=title.trim()||suggested;fileData(f).then(function(dataUrl){return ticketPut({id:crypto.randomUUID(),placeKey:key,title:title,fileName:f.name,dataUrl:dataUrl,createdAt:Date.now()})}).then(function(){file.value='';form.elements.title.value='';renderTicketList(list,key);renderTicketShortcuts(document);toast('附件按钮已生成')}).catch(function(){toast('文件保存失败')})};renderTicketList(list,key)}
function openTicketVaultV2(button){var key=button.dataset.ticketKey,name=button.dataset.ticketName,modal=document.createElement('div'),selectedFile=null;modal.className='trip-ticket-overlay';modal.innerHTML='<section class="trip-ticket-panel" role="dialog" aria-modal="true" aria-label="收藏夹"><header><div><small>TICKET VAULT · 本机保存</small><h3>'+esc(name)+'</h3></div><button type="button" data-ticket-close aria-label="关闭">×</button></header><form><label>按钮名称<input name="title" maxlength="60" placeholder="例如：门票 / 预约单 / 小红书攻略"></label><label>网页或小红书分享链接（可选）<input name="url" type="text" inputmode="url" placeholder="可粘贴网址或整段小红书分享文字"></label><label class="trip-ticket-file">＋ 选择 PDF 或图片<input name="file" type="file" accept="application/pdf,image/*"></label><span class="trip-ticket-file-name" data-ticket-file-name>尚未选择文件</span><button class="trip-ticket-save" type="submit">保存收藏</button></form><div class="trip-ticket-list"></div><p class="trip-ticket-note">填写的按钮名称同时用于链接、图片和 PDF。粘贴链接或选择一个文件后，点击“保存收藏”生成按钮。</p></section>';document.body.appendChild(modal);var list=$('.trip-ticket-list',modal),form=$('form',modal),file=form.elements.file,fileName=$('[data-ticket-file-name]',modal);function close(){modal.remove()}$('[data-ticket-close]',modal).onclick=close;modal.onclick=function(e){if(e.target===modal)close()};file.onchange=function(){selectedFile=file.files[0]||null;fileName.textContent=selectedFile?selectedFile.name:'尚未选择文件'};form.onsubmit=function(e){e.preventDefault();var raw=form.elements.url.value.trim(),url=raw?extractSavedUrl(raw):'',title=form.elements.title.value.trim();if(raw&&!url){toast('没有识别到有效链接');return}if(selectedFile){if(selectedFile.size>20*1024*1024){toast('文件请控制在20MB以内');return}var f=selectedFile,fileTitle=title||f.name.replace(/\.[^.]+$/,'');fileData(f).then(function(dataUrl){return ticketPut({id:crypto.randomUUID(),placeKey:key,title:fileTitle,fileName:f.name,dataUrl:dataUrl,createdAt:Date.now()})}).then(function(){renderTicketShortcuts(document);toast((/^image\//.test(f.type)?'图片':'PDF')+'已收藏');close()}).catch(function(){toast('文件保存失败')});return}if(url){var isXhs=/xhslink\.(?:cn|com)|xiaohongshu\.com/i.test(url);ticketPut({id:crypto.randomUUID(),placeKey:key,title:title||(isXhs?'小红书攻略':url),url:url,createdAt:Date.now()}).then(function(){renderTicketShortcuts(document);toast('链接已收藏');close()});return}toast('请粘贴链接或选择图片/PDF')};renderTicketList(list,key)}
